arguments.command:
cd /app && python3 -c "
import subprocess
def revcomp(s):
    c={'a':'t','t':'a','g':'c','c':'g'}
    return ''.join(c[x] for x in reversed(s))
def tm(seq):
    r=subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',seq.upper()],capture_output=True,text=True)
    return float(r.stdout.strip())
seqs={}
name=None
for line in open('sequences.fasta'):
    line=line.strip()
    if line.startswith('>'):
        name=line[1:]; seqs[name]=''
    else:
        seqs[name]+=line
inp=seqs['input']
p=215
up=inp[:p]; down=inp[p:]
print('FWD anneal (downstream) Tm by length:')
for L in range(15,31):
    print(L, round(tm(down[:L]),2))
print('REV anneal (revcomp upstream) Tm by length:')
for L in range(15,31):
    print(L, round(tm(revcomp(up[-L:])),2))
"

